import type { Elements, EngineInterface, RenderElement, RenderViewport, Register } from 'claude-code'

import type { Picture } from '../types'

type Engine = EngineInterface
type Target = { id: string; name: string; path?: string; url?: string }
type Place = { home: string | undefined; cwd: string }

const MAX_PER_ROW = 4
// Larger images are scaled down to this many pixels on their long side.
const MAX_PIXELS = 2048
const MAX_DOWNLOAD = 25_000_000
// A picture's natural width: one column for this many pixels.
const PIXELS_PER_COLUMN = 9

// From the userConfig options. No API reports a cell's size in pixels, so its
// shape is a setting. kitty fits a picture inside its box and centres it, so a
// box taller than the picture leaves empty bands above and below.
const sizing = { cellAspect: 2.4, maxColumns: 80, maxRows: 24 }

const EXT = 'png|jpe?g|gif|webp|bmp|svg|avif|tiff?|ico|heic'
const IMAGE_FILE = new RegExp(`\\.(?:${EXT})$`, 'i')
// A link or path stands between these in prose, markdown and code spans.
const BEFORE = '(?<=^|[\\s(\\[<`\'"])'
const AFTER = '(?=$|[\\s)\\]>`\'".,;:!?])'
const CHARS = '[^\\s()\\[\\]<>`\'"]'
const MARKDOWN_IMAGE = /!\[[^\]]*\]\(\s*<?([^)\s>]+)>?(?:\s+"[^"]*")?\s*\)/g
const LINK = new RegExp(
  `${BEFORE}(?:https?://${CHARS}+?\\.(?:${EXT})(?:[?#]${CHARS}*)?|[~/]${CHARS}*?\\.(?:${EXT}))${AFTER}`,
  'gi',
)
// The text block the engine stores beside an image pasted into a prompt.
const PASTED = /\[Image: source: ([^\]\n]+)\]/g

const pictures = { plugin: 'inline-images', key: 'pictures' } as const
const pasted = { plugin: 'inline-images', key: 'pasted' } as const
const calls = { plugin: 'inline-images', key: 'calls' } as const

function extract(text: string): string[] {
  const found = [...text.matchAll(MARKDOWN_IMAGE)].map(match => match[1] ?? '')
  found.push(...(text.match(LINK) ?? []))
  return found.filter(ref => ref !== '')
}

function imagesOf(tool: string, input: unknown): string[] {
  const fields = (typeof input === 'object' && input !== null ? input : {}) as Record<string, unknown>
  const named =
    tool === 'Read' ? [fields.file_path] : tool === 'SendUserFile' && Array.isArray(fields.files) ? fields.files : []
  return named.filter((value): value is string => typeof value === 'string' && IMAGE_FILE.test(value))
}

async function hash(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text))
  return [...new Uint8Array(digest)]
    .slice(0, 16)
    .map(byte => byte.toString(16).padStart(2, '0'))
    .join('')
}

async function place($: Engine): Promise<Place> {
  return { home: await $.env.get('HOME'), cwd: await $.session.cwd() }
}

async function cacheDir($: Engine): Promise<string> {
  const base = (await $.env.get('XDG_CACHE_HOME')) || `${await $.env.get('HOME')}/.cache`
  return `${base}/inline-images-mod`
}

// A local file is keyed by its modification time too, so an image rewritten
// under the same name (a fresh screenshot) is prepared again.
async function locate($: Engine, ref: string, where: Place): Promise<Target | undefined> {
  const name = ref.replace(/[?#].*$/, '').split('/').pop() || ref
  if (/^https?:\/\//i.test(ref)) return { id: await hash(ref), name, url: ref }

  let path = ref.replace(/^file:\/\//, '')
  if (path.startsWith('~/')) {
    if (where.home === undefined) return undefined
    path = where.home + path.slice(1)
  } else if (!path.startsWith('/')) {
    path = `${where.cwd}/${path}`
  }
  const stat = await $.fs.stat(path).catch(() => undefined)
  if (stat?.kind !== 'file') return undefined
  return { id: await hash(`${path}@${stat.mtimeMs}`), name, path }
}

async function run($: Engine, argv: string[], timeoutMs = 30_000): Promise<string> {
  const ran = await $.process.run(argv, { timeoutMs })
  if (ran.exitCode !== 0) {
    throw new Error(ran.stderr.trim().split('\n')[0] || `${argv[0]} exited with ${ran.exitCode}`)
  }
  return ran.stdout
}

// The terminal draws PNG alone, so anything else is converted with ImageMagick.
async function prepare($: Engine, target: Target): Promise<Picture> {
  const cache = await cacheDir($)
  await run($, ['mkdir', '-p', cache])

  let input = target.path ?? `${cache}/${target.id}.download`
  if (target.url !== undefined && !(await $.fs.exists(input))) {
    const part = `${input}.part`
    await run(
      $,
      ['curl', '-sSfL', '--connect-timeout', '5', '--max-time', '10', '--max-filesize', String(MAX_DOWNLOAD), '-o', part, target.url],
      20_000,
    )
    await run($, ['mv', part, input])
  }

  const info = (await run($, ['magick', 'identify', '-format', '%m %w %h\\n', `${input}[0]`])).split('\n')[0] ?? ''
  const [format = '', w = '', h = ''] = info.trim().split(' ')
  const width = Number(w)
  const height = Number(h)
  if (!(width > 0 && height > 0)) throw new Error('not an image ImageMagick can read')
  if (format === 'PNG' && Math.max(width, height) <= MAX_PIXELS) {
    return { status: 'ready', file: input, width, height }
  }

  const png = `${cache}/${target.id}.png`
  if (!(await $.fs.exists(png))) {
    const size = `${MAX_PIXELS}x${MAX_PIXELS}>`
    await run($, ['magick', '-background', 'none', `${input}[0]`, '-resize', size, `png:${png}`], 60_000)
  }
  return { status: 'ready', file: png, width, height }
}

// Rows are rounded down so the box is never taller than the picture, and the
// columns are then cut to what the picture fills at that height.
function fit(width: number, height: number, viewport: RenderViewport | undefined) {
  const { cellAspect, maxColumns, maxRows } = sizing
  const roomColumns = Math.max(8, Math.min(maxColumns, (viewport?.columns ?? 80) - 8))
  const roomRows = Math.max(4, Math.min(maxRows, Math.floor((viewport?.rows ?? 40) * 0.6)))
  const natural = Math.min(roomColumns, Math.max(1, Math.round(width / PIXELS_PER_COLUMN)))
  const rows = Math.min(roomRows, Math.max(1, Math.floor((natural * height) / width / cellAspect)))
  const columns = Math.max(1, Math.min(natural, Math.ceil((rows * cellAspect * width) / height)))
  return { columns: Math.min(columns, 255), rows: Math.min(rows, 255) }
}

function numberOr(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : fallback
}

// Each image's preparation, so a row drawn while it runs does not start another.
const jobs = new Map<string, Promise<void>>()

function ensure($: Engine, target: Target): Promise<void> {
  const known = jobs.get(target.id)
  if (known !== undefined) return known
  const job = (async () => {
    const ref = { ...pictures, id: target.id }
    if ((await $.state.get(ref)).value !== undefined) return
    const picture = await prepare($, target).catch(
      (error: unknown): Picture => ({ status: 'failed', reason: error instanceof Error ? error.message : String(error) }),
    )
    await $.state.set(ref, picture)
  })()
  jobs.set(target.id, job)
  return job
}

async function prepareAll($: Engine, refs: string[]): Promise<void> {
  const unique = [...new Set(refs)].slice(0, MAX_PER_ROW)
  if (unique.length === 0) return
  const where = await place($)
  const targets = await Promise.all(unique.map(ref => locate($, ref, where)))
  await Promise.all(targets.map(target => (target === undefined ? undefined : ensure($, target))))
}

// Draws the pictures under the engine's row. A picture not prepared yet is
// prepared from a timer, since a render hook may not write state; reading
// its state here redraws the row once it is written.
async function pictured(
  $: Engine,
  e: { viewport?: RenderViewport },
  table: Elements['terminal'],
  row: RenderElement,
  refs: string[],
): Promise<RenderElement> {
  const unique = [...new Set(refs)].slice(0, MAX_PER_ROW)
  if (unique.length === 0) return row
  const where = await place($)
  const targets = (await Promise.all(unique.map(ref => locate($, ref, where)))).filter(
    (target): target is Target => target !== undefined,
  )
  if (targets.length === 0) return row

  const { Box, Image, Text } = table
  const items = await Promise.all(
    targets.map(async target => {
      const { value } = await $.state.get({ ...pictures, id: target.id })
      if (value === undefined) {
        if (!jobs.has(target.id)) $.clock.after(0, () => void ensure($, target))
        return (
          <Box key={target.id}>
            <Text dimColor>⎿ {target.name}: preparing…</Text>
          </Box>
        )
      }
      if (value.status === 'failed') {
        return (
          <Box key={target.id}>
            <Text dimColor wrap="truncate-end">
              ⎿ {target.name}: {value.reason}
            </Text>
          </Box>
        )
      }
      const { columns, rows } = fit(value.width, value.height, e.viewport)
      return (
        <Box key={target.id} flexDirection="column">
          <Text dimColor wrap="truncate-end">
            ⎿ {target.name} · {value.width}×{value.height}
          </Text>
          <Image
            key={target.id}
            source={{ file: value.file, format: 'png' }}
            columns={columns}
            rows={rows}
            alt={`[image: ${target.name}]`}
          />
        </Box>
      )
    }),
  )

  return (
    <Box flexDirection="column">
      {row}
      <Box flexDirection="column" paddingLeft={2}>
        {items}
      </Box>
    </Box>
  )
}

// A prompt row with images is drawn under an id that keeps the first four
// groups of the stored row's uuid and numbers the last, so both are keyed by
// that prefix.
function prefixOf(id: string): string | undefined {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-/i.test(id) ? id.slice(0, 23) : undefined
}

function textsOf(content: readonly { type: string; text?: unknown }[]): string[] {
  return content.flatMap(block => (block.type === 'text' && typeof block.text === 'string' ? [block.text] : []))
}

// The prompts already looked for in the conversation, by prefix.
const searched = new Set<string>()

// A prompt stored before this mod loaded, or in a resumed session, has no
// entry in `pasted`; its files are found in the conversation by the prompt's
// [Image #N] markers, newest message first.
async function findPasted($: Engine, prefix: string, markers: string[]): Promise<void> {
  const ref = { ...pasted, id: prefix }
  if ((await $.state.get(ref)).value !== undefined) return
  const messages = await $.session.messages({ as: 'api' })
  if (!Array.isArray(messages)) return
  for (const message of [...messages].reverse()) {
    if (message.role !== 'user' || typeof message.content === 'string') continue
    const joined = textsOf(message.content).join('\n')
    if (!markers.every(marker => joined.includes(marker))) continue
    const files = [...joined.matchAll(PASTED)].map(match => match[1] ?? '').filter(file => file !== '')
    if (files.length === 0) continue
    await $.state.set(ref, files)
    await prepareAll($, files)
    return
  }
}

async function noteCall($: Engine, toolUseId: string, refs: string[]): Promise<void> {
  if (refs.length === 0) return
  await $.state.set({ ...calls, id: toolUseId }, refs)
  await prepareAll($, refs)
}

export const register: Register = (on, options) => {
  sizing.cellAspect = numberOr(options.cellAspect, 2.4)
  sizing.maxColumns = Math.round(numberOr(options.maxColumns, 80))
  sizing.maxRows = Math.round(numberOr(options.maxRows, 24))

  // Preparing when a row is stored, and when a tool call ends, gets most
  // pictures ready before their row is first drawn.
  on('session.append', async ($, e, next) => {
    if (e.agentId === undefined && (e.message.type === 'user' || e.message.type === 'assistant')) {
      const texts = textsOf(e.message.content)
      const files = texts.flatMap(text => [...text.matchAll(PASTED)].map(match => match[1] ?? ''))
      const prefix = prefixOf(e.uuid)
      if (e.message.type === 'user' && files.length > 0 && prefix !== undefined) {
        await $.state.set({ ...pasted, id: prefix }, files)
      }
      await prepareAll($, [...files, ...texts.flatMap(extract)])
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'Read' }, async ($, e, next) => {
    const ran = await next(e)
    if (ran.deny === undefined && ran.isError !== true) await noteCall($, e.tool_use_id, imagesOf(e.tool, e))
    return ran
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'SendUserFile' }, async ($, e, next) => {
    const ran = await next(e)
    if (ran.deny === undefined && ran.isError !== true) await noteCall($, e.tool_use_id, imagesOf(e.tool, e))
    return ran
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'UserMessage', surface: 'terminal' }, async ($, e, next) => {
    const prefix = prefixOf(e.requestId)
    const markers = e.props.text.match(/\[Image #\d+\]/g) ?? []
    let files: string[] = []
    if (prefix !== undefined && markers.length > 0) {
      files = (await $.state.get({ ...pasted, id: prefix })).value ?? []
      // A second's wait lets the row's own store land first.
      if (files.length === 0 && !searched.has(prefix)) {
        searched.add(prefix)
        $.clock.after(1000, () => void findPasted($, prefix, markers).catch(() => undefined))
      }
    }
    const refs = [...files, ...extract(e.props.text)]
    return refs.length === 0 ? next(e) : pictured($, e, $.ui.resolve(e), await next(e), refs)
  })

  on('ui.render', { component: 'AssistantMessage', surface: 'terminal' }, async ($, e, next) => {
    const refs = e.props.isSummary ? [] : extract(e.props.text)
    return refs.length === 0 ? next(e) : pictured($, e, $.ui.resolve(e), await next(e), refs)
  })

  // A Read or SendUserFile row of its own (SendUserFile's always; a Read's in
  // the ctrl+o transcript): under its result, which draws the file's line.
  on('ui.render', { component: 'ToolResult', surface: 'terminal' }, async ($, e, next) => {
    const { tool, tool_use_id, isErrored } = e.props
    if (isErrored || (tool !== 'Read' && tool !== 'SendUserFile')) return next(e)
    const refs = (await $.state.get({ ...calls, id: tool_use_id })).value ?? []
    return refs.length === 0 ? next(e) : pictured($, e, $.ui.resolve(e), await next(e), refs)
  })

  // Reads folded into one line (`Read 2 files`). A SendUserFile call in the
  // group is drawn by its result, after the group.
  on('ui.render', { component: 'ToolGroup', surface: 'terminal' }, async ($, e, next) => {
    const refs = e.props.isExpanded
      ? []
      : e.props.calls.flatMap(call =>
          call.tool !== 'Read' || call.isRunning || call.isErrored || call.isInterrupted
            ? []
            : imagesOf(call.tool, call.input),
        )
    return refs.length === 0 ? next(e) : pictured($, e, $.ui.resolve(e), await next(e), refs)
  })
}

