// An image made ready for the terminal: a PNG file it can read, with the
// original image's size in pixels; or why it could not be made ready.
export type Picture =
  | { status: 'ready'; file: string; width: number; height: number }
  | { status: 'failed'; reason: string }

declare module 'claude-code' {
  interface PluginState {
    'inline-images': {
      // Keyed by a hash of the image's path and modification time, or its URL.
      pictures: StateFamily<Picture>
      // The files of the images pasted into a prompt, keyed by the first four
      // groups of the prompt row's uuid, which its drawn row's id shares.
      pasted: StateFamily<string[]>
      // The image files a Read or SendUserFile call named, keyed by tool_use_id.
      calls: StateFamily<string[]>
    }
  }
}
